-- ONLY the captured closed qg-e2e-sandbox catalogue. Never run on production.
begin;
set local lock_timeout='2s';
set local statement_timeout='30s';
do $$ begin
 if exists(select 1 from cron.job where active) or not exists(select 1 from auth.users where id='8ec6113d-7b78-4c69-a90c-86d0e4b69714' and email='sandbox.guard@example.invalid')
 or not exists(select 1 from app.payment_audit_logs where id='b08b2911-9e16-4aa5-b1b9-202611220200' and metadata->>'phase'='closed')
 or (select md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' order by id),'')) from app.subscriptions t)<>'0fa2d0b9c56a05b44185f63da5e5fe7c'
 or (select md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' order by user_id),'')) from app.user_entitlements_data t)<>'f600d0d2cf5ea97c024ace574de3f0fb' then raise exception 'Captured closed sandbox baseline required';end if;
end $$;
delete from app.plan_fee_rules where plan_slug in ('client_free','client-pro','client-enterprise');
delete from app.plans where slug in ('client_free','client-pro','client-enterprise','guard_starter');
